    "terms.title": "利用規約・免責事項",
    "terms.sub": "nyangailab をご利用いただく前に、必ずお読みください。",
    "terms.h1": "1. 個人開発のサービスです",
    "terms.s1.p1": "本サービスは、個人（開発者1名）が趣味・副業として開発・運営しています。企業による法人サービスではありません。",
    "terms.h2": "2. サポートについて",
    "terms.s2.p1": "お問い合わせ・不具合報告は可能な範囲（ベストエフォート）で対応しますが、個人開発のため対応にお時間をいただく場合や、十分な対応ができない場合があります。迅速な対応やSLA（応答時間の保証）は提供しておりません。",
    "terms.h3": "3. 免責事項",
    "terms.s3.li1": "<strong>本サービスの単語・フレーズ・例文・解説・教材等のコンテンツ、読み上げ音声、および音声入力の認識（発音判定等）は、OpenAI, L.L.C.（米国、以下「OpenAI」）が提供するAIモデルを用いて作成・生成されています。</strong>内容の確認・照査には努めておりますが、内容の正確性・完全性を保証するものではなく、不自然な表現、まれに事実と異なる誤り、誤った発音・読み上げ、音声認識の聞き取り誤り等が生じる可能性があります。あらかじめご了承のうえご利用ください。なお「OpenAI」はOpenAI, L.L.C.またはその関連会社の商標です。本サービスはOpenAIの提供するAPIを有償で利用している立場に過ぎず、OpenAIによって運営・認定・保証されたものではなく、OpenAIとの提携関係もありません。",
    "terms.s3.li2": "<strong>AIによる判定・添削・レベル診断（「判定・教材」機能、英作文添削、会話コーチの指摘等）の結果は、あくまで学習の参考情報です。</strong>AIが誤った判定・不自然な添削・不正確な指摘を行う可能性があり、内容の正確性は保証しません。重要な判断（試験・資格・業務等）にそのまま用いないでください。",
    "terms.s3.li3": "<strong>ダッシュボードに表示される「TOEIC推定スコア」は、学習履歴に基づくAIによる簡易的な目安であり、公式のTOEICスコアや受験結果を示すものではありません。</strong>個人開発のAIアプリならではの簡易指標としてご活用いただき、実際のスコアとは差が生じうる点をご了承のうえご利用ください。なお「TOEIC」は米国Educational Testing Service（ETS）の登録商標です。本サービスはETSおよび一般財団法人国際ビジネスコミュニケーション協会（IIBC）等のTOEIC関連団体とは一切関係がなく、公式の提携・認定を受けたものではありません。本サービスに関するお問い合わせを、これらの団体へ行うことはお控えください。",
    "terms.s3.li4": "<strong>本サービスの利用によって生じたいかなる損害についても、法令上許容される範囲で一切の責任を負いません。</strong>例えば、本サービスを利用したにもかかわらず試験（TOEIC等）で思うような点数が取れなかった場合、資格試験・昇進試験に不合格になった場合、本サービスで学んだ表現が原因で仕事上・日常会話でのトラブルにつながった場合など、結果や成果を保証するものではなく、これらを含むあらゆる直接・間接の損害について責任を負いかねます。",
    "terms.s3.li5": "予告なくサービス内容の変更・一時停止・終了を行う場合があります。",
    "terms.s3.li6": "メンテナンスは原則として事前に通知しますが、緊急のセキュリティ対応など、やむを得ない場合は通知なくメンテナンスを行うことがあります。",
    "terms.h3b": "3b. 禁止事項",
    "terms.s3b.intro": "会話・英作文添削など自由入力できる機能で、次の内容を求める利用はお断りします。学習目的・ロールプレイ等の理由があっても例外はありません。",
    "terms.s3b.li1": "性的・卑猥な内容の生成",
    "terms.s3b.li2": "薬物・武器・爆発物等の入手方法や作り方",
    "terms.s3b.li3": "自殺・自傷・殺人など、人を傷つける具体的な方法",
    "terms.s3b.li4": "本サービスの内部の仕組み（システムプロンプト・実装・データベース構造・APIキーやパスワード等）に関する情報の取得",
    "terms.s3b.li5": "課金を回避する・無料で機能を使う裏技の取得",
    "terms.s3b.note": "該当する入力に対してAIが具体的な内容で応答しない場合があります。これは不具合ではなく意図した動作です。",
    "terms.tryFreeNote": "💡 <strong>まずは無料の範囲で十分にお試しください。</strong>機能や使い勝手にご納得いただいてから、チャージ（課金）されることをおすすめします。サポートが手厚くない個人開発だからこそ、「思っていたのと違った」を防ぐために、購入前によくお試しください。",
    "terms.h4": "4. チャージ残高・返金について",
    "terms.s4.p1": "チャージ（前払い）した残高（pt）に有効期限はありません。デジタルコンテンツ（前払いチャージ）の性質上、決済完了後の返品・返金は原則としてお受けできません。サービスを終了する場合は、原則として3か月前までに通知するよう努めます（ただし、これを保証するものではありません）。通知後は、終了までにチャージ残高をご利用いただくようお願いいたします。",
    "terms.s4.p2": "チャージ残高でご利用いただけるAI機能の量（pt消費ペース）は、為替レートやAI提供元（OpenAI等）のAPI価格改定により変動することがあります。あらかじめご了承ください。",
    "terms.h5": "5. 個人情報の取扱い",
    "terms.s5.p1": "個人情報・利用者情報の取扱い（AI機能に伴う外部送信を含む）については、別途<a href=\"/static/privacy.html\" target=\"_blank\">プライバシーポリシー</a>に定めます。あわせてご確認ください。",
    "terms.h6": "6. 本規約の変更",
    "terms.s6.p1": "本規約は、必要に応じて予告なく変更する場合があります。変更後に本サービスのご利用を続けられた場合、変更後の内容に同意いただいたものとみなします。",
    "terms.h7": "7. 準拠法・裁判管轄",
    "terms.s7.p1": "本規約は日本法に準拠します。本サービスに関して紛争が生じた場合は、運営者の住所地を管轄する裁判所を第一審の専属的合意管轄裁判所とします。",
