    "tokushoho.paymentMethodLabel": "お支払方法",
    "tokushoho.paymentMethodValue": "①アプリ内「PayPayで購入」ボタンからのPayPay直接決済（PayPay公式APIを通じた決済。決済手段はPayPayのみ）、または②決済窓口であるBASEを通じて、クレジットカード／PayPay／コンビニ・Pay-easy／キャリア決済／銀行振込／Amazon Pay／PayPal／あと払い（Pay ID）のいずれかがご利用いただけます。②の決済手段は決済窓口であるBASEのサービス内容に準じるため、BASE側の仕様変更により予告なく変更・追加・終了となる場合があります。最新の対応状況はBASEの案内をご確認ください。",
    "tokushoho.paymentTimingLabel": "お支払時期",
    "tokushoho.paymentTimingValue": "いずれの方法も、ご注文（お申し込み）時に決済されます。②BASE経由の場合、決済処理自体は決済窓口であるBASEのサービスに準じます。",
    "tokushoho.deliveryLabel": "商品の引渡し時期",
    "tokushoho.deliveryValue": "①PayPay直接決済は、決済完了と同時に即時、チャージ残高へ反映されます（キーの発行・入力は不要です）。②BASE経由の場合は、決済確認後、目安として1週間以内に、BASEの取引メッセージまたはメールでチャージキーをお送りします（個人運営のため即時発行を保証するものではありません）。",
    "tokushoho.returnsLabel": "返品・キャンセルについて",
    "tokushoho.returnsValue": "本サービスはデジタルコンテンツ（前払いチャージ残高）の性質上、決済完了後の返品・返金は原則お受けできません。<strong>ご購入前に、無料の範囲（未ログイン・ログイン無課金いずれでもお試しいただけます）でアプリの操作感や、ご利用の端末・ブラウザで発音の音声がきちんと再生されるかを、必ず事前にご確認ください。</strong>サービスを終了する場合は、原則として3か月前までに通知するよう努めます（ただし、これを保証するものではありません）。詳細は<a href=\"/static/terms.html\" target=\"_blank\">利用規約・免責事項</a>をご確認ください。",
    "tokushoho.envLabel": "動作環境",
