    "flashphrase.helpText": "実用フレーズをカード形式で次々に答え合わせする高速学習モードです。シーン・レベル・自分のフレーズ帳から出題範囲を選べます。",
    "flashphrase.intro": "フレーズ帳をどんどんめくる高速学習。カードをタップで答え、スワイプ（または下のボタン）で採点します。",
    "flashphrase.deckSelectTitle": "自分のフレーズ帳から選んでフラッシュする（選ぶとシーン・レベルの絞り込みと併用できます）",
