    "tokushoho.priceLabel": "Sale price",
    "tokushoho.priceValue": "Two credit packs: ¥800 (800pt) / ¥8,000 (8,800pt). All prices include tax. Prices may be revised without prior notice.",
    "tokushoho.extraFeeLabel": "Costs other than the sale price",
    "tokushoho.extraFeeValue": "None (payment processing fees are borne by us). You are responsible for your own data/communication charges.",
    "tokushoho.paymentMethodLabel": "Payment methods",
    "tokushoho.paymentMethodValue": "① Direct PayPay payment via the “Buy with PayPay” button in the app (processed through PayPay's official API; PayPay only), or ② via our payment provider BASE: credit card / PayPay / convenience store · Pay-easy / carrier billing / bank transfer / Amazon Pay / PayPal / deferred payment (Pay ID). Method ②'s options follow BASE's own service and may change, be added, or be discontinued without notice due to changes on BASE's side. Please check BASE's own information for the latest details.",
    "tokushoho.paymentTimingLabel": "Timing of payment",
    "tokushoho.paymentTimingValue": "For either method, payment is taken at the time of your order. For ② (via BASE), the payment process itself follows BASE's own service.",
    "tokushoho.deliveryLabel": "Timing of delivery",
    "tokushoho.deliveryValue": "① Direct PayPay payments are reflected in your credit balance immediately upon payment (no key to issue or enter). ② For BASE orders, we send a charge key via a BASE order message or email, typically within about a week after payment is confirmed (as this is an individually run service, immediate issuance is not guaranteed).",
    "tokushoho.returnsLabel": "Returns and cancellations",
    "tokushoho.returnsValue": "Due to the nature of this service as digital content (prepaid credit balance), we generally cannot accept returns or refunds once payment is complete. <strong>Before purchasing, please be sure to try the free range of the app (available whether or not you are signed in) to check how it feels to use and confirm that pronunciation audio plays correctly on your device and browser.</strong> If we discontinue the service, we will endeavor to give notice at least 3 months in advance as a general rule (though this cannot be guaranteed). See the <a href=\"/static/terms.html\" target=\"_blank\">Terms of Service &amp; Disclaimer</a> for details.",
    "tokushoho.envLabel": "System requirements",
    "tokushoho.envValue": "The service is intended for use with a modern browser that supports the Web Speech API (speech synthesis / recognition), such as a recent version of Google Chrome. Depending on your device and browser settings, some features (such as microphone use) may not work. Recommended requirements may change without notice as browser technology evolves.",
