    "settings.title": "Settings",
    "settings.helpText": "This screen brings together your profile, credit, which topics/scenes are shown, default filters, advanced settings (mastery thresholds, etc.), AI voice, and contact/feedback. Changes to topics/scenes or default filters only take effect once you press “Save” on that card.",
