    "settings.masteryConfigTitle": "Mastery & forgetting-curve settings",
    "settings.masteryConfigHelp": "The forgetting curve is a mechanism where mastery pt automatically decreases little by little over time. Without review, items will drop out of “learned” status. Items marked “graduated” don't decrease. Set the decrease amount to 0 to turn it off.",
    "settings.masteryConfigNote": "Word/phrase mastery is managed as 0 up to a maximum number of pt (points); reaching the pt you set is judged as “learned”. You can also adjust the bonus from the “Learned”/“Somewhat” buttons here, and the strength of the forgetting curve that naturally reduces it over time. Changes here apply across all learning features on your account — word lists, phrase lists, flashcards, etc. (not set per individual list). Values are automatically adjusted to a safe range when saved.",
