    "flashphrase.title": "Phrase flashcards",
    "flashphrase.helpText": "A fast-paced study mode where you check answers for practical phrases one card after another. You can choose the range by scene, level, or your own phrase lists.",
    "flashphrase.intro": "Fast-paced study — flip through your phrase list. Tap a card to reveal the answer, then swipe (or use the buttons below) to grade it.",
