    "tokushoho.paymentMethodLabel": "付款方式",
    "tokushoho.paymentMethodValue": "①通过应用内「使用PayPay购买」按钮进行PayPay直接付款（通过PayPay官方API处理，仅支持PayPay）；或②通过支付渠道BASE，可选择信用卡／PayPay／便利店・Pay-easy／运营商代收费／银行转账／Amazon Pay／PayPal／延后付款（Pay ID）中的任意一种。②的付款方式依据支付渠道BASE的服务内容而定，可能因BASE方规格变更而在不预先通知的情况下变更、增加或终止。最新支持情况请以BASE的说明为准。",
    "tokushoho.paymentTimingLabel": "付款时间",
    "tokushoho.paymentTimingValue": "无论哪种方式，均在您下单（申请）时完成付款。②经由BASE的情况下，付款处理本身依据支付渠道BASE的服务而定。",
    "tokushoho.deliveryLabel": "商品交付时间",
    "tokushoho.deliveryValue": "①PayPay直接付款：付款完成后立即反映到充值余额中（无需发放或输入密钥）。②经由BASE的情况下：付款确认后，我们会通过BASE的交易消息或邮件发送充值密钥，通常约在1周内完成（因属个人运营，不保证即时发放）。",
    "tokushoho.returnsLabel": "关于退货・取消",
    "tokushoho.returnsValue": "鉴于本服务属于数字内容（预付充值余额）性质，付款完成后原则上无法办理退货・退款。<strong>购买前，请务必先在免费范围内（无论是否登录均可试用）确认应用的操作体验，以及在您所用设备・浏览器上发音语音是否能正常播放。</strong>如需终止服务，我们将原则上努力在3个月前进行通知（但不保证一定能做到）。详情请参见<a href=\"/static/terms.html\" target=\"_blank\">使用条款・免责事项</a>。",
    "tokushoho.envLabel": "运行环境",
    "tokushoho.envValue": "本服务预期在支持Web Speech API（语音合成・语音识别）的现代浏览器（如最新版Google Chrome等）中使用。根据您所用设备・浏览器的设置，部分功能（如麦克风使用等）可能无法正常运作。推荐的运行环境条件可能会随浏览器等技术发展而在不预先通知的情况下变更。",
