    "tokushoho.deliveryValue": "①PayPay直接付款：付款完成後立即反映到儲值餘額中（無需發放或輸入金鑰）。②經由BASE的情況下：付款確認後，我們會透過BASE的交易訊息或郵件發送儲值金鑰，通常約在1週內完成（因屬個人營運，不保證即時發放）。",
    "tokushoho.returnsLabel": "關於退貨・取消",
    "tokushoho.returnsValue": "鑑於本服務屬於數位內容（預付儲值餘額）性質，付款完成後原則上無法辦理退貨・退款。<strong>購買前，請務必先在免費範圍內（無論是否登入均可試用）確認應用程式的操作體驗，以及在您所用裝置・瀏覽器上發音語音是否能正常播放。</strong>如需終止服務，我們將原則上努力在3個月前進行通知（但不保證一定能做到）。詳情請參見<a href=\"/static/terms.html\" target=\"_blank\">使用條款・免責事項</a>。",
    "tokushoho.envLabel": "運行環境",
    "tokushoho.envValue": "本服務預期在支援Web Speech API（語音合成・語音辨識）的現代瀏覽器（如最新版Google Chrome等）中使用。根據您所用裝置・瀏覽器的設定，部分功能（如麥克風使用等）可能無法正常運作。推薦的運行環境條件可能會隨瀏覽器等技術發展而在不預先通知的情況下變更。",
